{
  "name": "checkout-service",
  "private": true,
  "scripts": {
    "lint": "eslint .",
    "test": "vitest run",
    "build": "vite build && cp release/deploy.sh dist/deploy.sh"
  },
  "devDependencies": {
    "eslint": "9.0.0",
    "vitest": "3.0.0",
    "vite": "6.0.0"
  }
}

{
  "baseline": {
    "event": {
      "name": "push",
      "ref": "refs/heads/main",
      "sha": "commit-43",
      "repository": "acme/checkout",
      "actor": "developer",
      "paths": [
        "backend/app.js"
      ]
    },
    "checks": {
      "lint": {
        "passed": true,
        "message": "lint fixture passed"
      },
      "unit": {
        "passed": true,
        "message": "unit fixture passed"
      },
      "build": {
        "passed": true,
        "message": "build fixture passed"
      },
      "integration": {
        "passed": true,
        "message": "integration fixture passed"
      },
      "audit": {
        "passed": true,
        "message": "audit fixture passed"
      },
      "smoke": {
        "passed": true,
        "message": "smoke fixture passed"
      }
    },
    "runners": [
      {
        "name": "hosted-linux",
        "labels": [
          "ubuntu-latest"
        ],
        "group": "hosted",
        "os": "Linux",
        "ephemeral": true,
        "trusted": false,
        "available": true
      },
      {
        "name": "hosted-windows",
        "labels": [
          "windows-latest"
        ],
        "group": "hosted",
        "os": "Windows",
        "ephemeral": true,
        "trusted": false,
        "available": true
      },
      {
        "name": "release-worker",
        "labels": [
          "self-hosted",
          "linux",
          "release"
        ],
        "group": "production",
        "os": "Linux",
        "ephemeral": true,
        "trusted": true,
        "available": true
      },
      {
        "name": "legacy-worker",
        "labels": [
          "self-hosted",
          "linux"
        ],
        "group": "legacy",
        "os": "Linux",
        "ephemeral": false,
        "trusted": false,
        "available": true
      }
    ],
    "actionRefs": {
      "actions/checkout@v6": "checkout",
      "actions/setup-node@v7": "node",
      "actions/cache@v4": "cache",
      "actions/upload-artifact@v4": "upload",
      "actions/download-artifact@v4": "download",
      "aws-actions/configure-aws-credentials@v5": "oidc"
    },
    "role": "arn:aws:iam::123456789012:role/checkout-production",
    "trustFile": "cloud-trust.json",
    "settingsFile": "environment-settings.json",
    "approved": true,
    "approvalActor": "release-manager"
  },
  "cases": [
    {
      "id": "release",
      "title": "Approved healthy main",
      "description": "Approved healthy main. Compare the evidence with the success criteria.",
      "github": {}
    },
    {
      "id": "failed-tests",
      "title": "Failed validation",
      "description": "Failed validation. Compare the evidence with the success criteria.",
      "github": {
        "checks": {
          "lint": {
            "passed": true,
            "message": "lint fixture passed"
          },
          "unit": {
            "passed": false,
            "message": "Checkout regression"
          },
          "build": {
            "passed": true,
            "message": "build fixture passed"
          },
          "integration": {
            "passed": true,
            "message": "integration fixture passed"
          },
          "audit": {
            "passed": true,
            "message": "audit fixture passed"
          },
          "smoke": {
            "passed": true,
            "message": "smoke fixture passed"
          }
        }
      }
    },
    {
      "id": "fork",
      "title": "Untrusted contributor",
      "description": "Untrusted contributor. Compare the evidence with the success criteria.",
      "github": {
        "event": {
          "name": "pull_request",
          "ref": "refs/pull/9/merge",
          "sha": "commit-43",
          "repository": "acme/checkout",
          "actor": "developer",
          "paths": [
            "backend/app.js"
          ],
          "fork": true,
          "base": "main"
        }
      }
    },
    {
      "id": "approval",
      "title": "Approval absent",
      "description": "Approval absent. Compare the evidence with the success criteria.",
      "github": {
        "approved": false
      }
    },
    {
      "id": "repository",
      "title": "Wrong repository",
      "description": "Wrong repository. Compare the evidence with the success criteria.",
      "github": {
        "event": {
          "name": "push",
          "ref": "refs/heads/main",
          "sha": "commit-43",
          "repository": "outsider/checkout",
          "actor": "developer",
          "paths": [
            "backend/app.js"
          ]
        }
      }
    }
  ]
}

#!/usr/bin/env bash
set -euo pipefail
printf "Release operation: apply the accompanying app.json to the authorized target.\n"

#!/usr/bin/env bash
set -euo pipefail
printf "Status operation: publish the validated revision with the job token.\n"

